// Explicit pin inventories; legacy wiring is preserved as named pins.
function pinList(value){return String(value||'').split(/[,;\n]+/).map(s=>s.trim()).filter(Boolean).map(name=>({name,type:'unspecified',notes:''}));}
function migratePins(p){for(const n of p.nodes){n.pins=Array.isArray(n.pins)?n.pins:pinList(n.pins);}for(const n of p.nodes)for(const c of n.connections||[]){const target=p.nodes.find(x=>x.id===c.target);for(const [board,name,id] of [[n,c.local,c.localPinId],[target,c.remote,c.remotePinId]])if(board&&!id&&!board.pins.some(p=>p.name===name))board.pins.push({name,type:'unspecified',notes:''});}return p;}
const originalValidate=validate;
validate=function(p){const result=originalValidate(p);for(const n of result.nodes){if(n.pins!=null&&(!Array.isArray(n.pins)||n.pins.some(p=>!p||typeof p.name!=='string'||!p.name.trim()||p.name.length>80)))throw Error('Pins must be an array of named pins (up to 80 characters each).');if(n.pins&&new Set(n.pins.map(p=>p.name.trim().toLowerCase())).size!==n.pins.length)throw Error(`Duplicate pin names on ${n.name}. Use unique names such as GND1 and GND2.`);if((n.pins||[]).length>100)throw Error('Use 100 pins or fewer per component.');}migratePins(result);if(result.baseline)result.baseline=migratePins({nodes:originalValidate({name:'baseline',nodes:result.baseline}).nodes}).nodes;return result;};
migratePins(project);if(project.baseline)migratePins({nodes:project.baseline});
function wireRecords(){const seen=new Set(),out=[];for(const n of project.nodes)for(const [index,c] of n.connections.entries()){const key=[JSON.stringify([n.id,c.local]),JSON.stringify([c.target,c.remote])].sort().join('|');if(!seen.has(key)){seen.add(key);out.push({source:n,target:node(c.target),connection:c,index});}}return out;}
function saveWire(source,local,targetId,remote){const target=node(targetId);if(!source||!target||source.id===target.id)throw Error('Choose a different component.');if(!source.pins.some(p=>p.name===local)||!target.pins.some(p=>p.name===remote))throw Error('Choose a defined pin at both ends.');const exists=wireRecords().some(w=>(w.source.id===source.id&&w.connection.local===local&&w.target.id===targetId&&w.connection.remote===remote)||(w.source.id===targetId&&w.connection.local===remote&&w.target.id===source.id&&w.connection.remote===local));if(exists)throw Error('These pins are already connected.');source.connections.push({local,target:targetId,remote});}
function wiresFor(n){return wireRecords().filter(w=>w.source.id===n.id||w.target?.id===n.id);}
function createModal(html){const d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.onclose=()=>d.remove();d.querySelector('[data-dismiss]').onclick=()=>d.close();return d;}
function chooseOptions(items,value){return items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');}
openConnection=function(n,initialPin=''){const others=project.nodes.filter(x=>x.id!==n.id&&categories[x.category][2]);if(!n.pins.length){toast('Add pins to this component first.');return;}if(!others.length){toast('Add another electronic component and define its pins first.');return;}const d=createModal(`<form><div class="dialog-heading"><h2>Connect pins</h2><button type="button" class="icon-button" data-dismiss>×</button></div><label>${esc(n.name)} pin<select name="local">${chooseOptions(n.pins.map(p=>[p.name,p.name]),initialPin)}</select></label><label>Connected component<select name="target">${chooseOptions(others.map(x=>[x.id,x.name]))}</select></label><label>Connected pin<select name="remote" required></select></label><p class="muted" id="wireHelp"></p><div class="dialog-actions"><button class="button primary" id="saveWireBtn">Connect pins</button></div></form>`);const target=d.querySelector('[name=target]'),remote=d.querySelector('[name=remote]');function refresh(){const pins=node(target.value)?.pins||[];remote.innerHTML=chooseOptions(pins.map(p=>[p.name,p.name]));d.querySelector('#wireHelp').textContent=pins.length?'Connections appear on both components and in the Wiring view.':'This component has no pins yet. Close this window and add its pins in component details.';d.querySelector('#saveWireBtn').disabled=!pins.length;}target.onchange=refresh;refresh();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));saveWire(n,v.local,v.target,v.remote);changed(`Connected ${n.name} ${v.local} to ${node(v.target).name} ${v.remote}`);renderInspector();d.close();}catch(e){toast(e.message);}};d.showModal();};
function editPin(n,index=null){const old=index==null?null:n.pins[index],others=project.nodes.filter(x=>x.id!==n.id&&categories[x.category][2]);const d=createModal(`<form><div class="dialog-heading"><h2>${old?'Edit':'Add'} pin</h2><button type="button" class="icon-button" data-dismiss>×</button></div><label>Pin name<input name="name" maxlength="80" required value="${esc(old?.name||'')}" placeholder="e.g. GPIO21 or GND1"></label><label>Pin type<select name="type">${chooseOptions(['unspecified','digital','analog','power','ground','I2C','SPI','UART','PWM'].map(t=>[t,t]),old?.type)}</select></label><label>Notes<input name="notes" value="${esc(old?.notes||'')}" placeholder="Voltage, function, or restrictions"></label><label>Connect to (optional)<select name="target"><option value="">Leave unconnected</option>${chooseOptions(others.map(x=>[x.id,x.name]))}</select></label><label>Target pin<select name="remote" disabled><option value="">Select a component first</option></select></label><p class="muted" id="pinHelp">Only pins you define are offered. No pinout is inferred from a board name.</p><div class="dialog-actions"><button class="button primary">Save pin</button></div></form>`);const target=d.querySelector('[name=target]'),remote=d.querySelector('[name=remote]');target.onchange=()=>{const pins=node(target.value)?.pins||[];remote.innerHTML=pins.length?chooseOptions(pins.map(p=>[p.name,p.name])):'<option value="">No pins defined</option>';remote.disabled=!pins.length;remote.required=!!target.value;d.querySelector('#pinHelp').textContent=target.value&&!pins.length?'Define pins on the target component first.':'This optional connection is added to any existing wires.';};d.querySelector('form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),name=v.name.trim();if(!name)return;if(n.pins.some((p,i)=>i!==index&&p.name.toLowerCase()===name.toLowerCase())){toast('This pin name already exists.');return;}if(index==null&&n.pins.length>=100){toast('Use 100 pins or fewer.');return;}if(v.target&&!(node(v.target)?.pins.some(p=>p.name===v.remote))){toast('Choose a defined target pin.');return;}if(old){for(const source of project.nodes)for(const c of source.connections){if(source.id===n.id&&c.local===old.name)c.local=name;if(c.target===n.id&&c.remote===old.name)c.remote=name;}}const pin={name,type:v.type,notes:v.notes};if(old)n.pins[index]=pin;else n.pins.push(pin);if(v.target){try{saveWire(n,name,v.target,v.remote);}catch(e){toast(e.message);}}changed(`${old?'Updated':'Added'} pin ${n.name} / ${name}`);renderInspector();d.close();};d.showModal();}
const originalInspector=renderInspector;
renderInspector=function(){originalInspector();const n=node(selected);if(!n||!categories[n.category][2])return;const section=document.createElement('section');section.className='pin-editor';section.innerHTML=`<div class="section-label">PIN INVENTORY <button id="addPin">＋ Add pin</button></div>${n.pins.map((p,i)=>`<div class="pin-item"><button class="pin-edit" data-edit-pin="${i}" title="Edit pin"><b>${esc(p.name)}</b><small>${esc(p.type||'unspecified')}${p.notes?' · '+esc(p.notes):''}</small></button><button data-connect-pin="${i}" title="Connect pin">↗</button><button data-delete-pin="${i}" aria-label="Delete ${esc(p.name)} pin">×</button></div>`).join('')||'<p class="muted">Add the pins available on this component.</p>'}`;$('#connectionAdd').closest('.section-label').before(section);$('#addPin').onclick=()=>editPin(n);$$('[data-edit-pin]').forEach(b=>b.onclick=()=>editPin(n,Number(b.dataset.editPin)));$$('[data-connect-pin]').forEach(b=>b.onclick=()=>openConnection(n,n.pins[Number(b.dataset.connectPin)].name));$$('[data-delete-pin]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.deletePin),name=n.pins[i].name;const count=wiresFor(n).filter(w=>w.source.id===n.id?w.connection.local===name:w.connection.remote===name).length;if(count&&!confirm(`Delete ${name} and its ${count} wire connection(s)?`))return;n.pins.splice(i,1);for(const src of project.nodes)src.connections=src.connections.filter(c=>!(src.id===n.id&&c.local===name)&&!(c.target===n.id&&c.remote===name));changed(`Deleted pin ${n.name} ${name}`);renderInspector();});const heading=$('#connectionAdd').closest('.section-label');let sibling=heading.nextElementSibling;while(sibling&&(sibling.classList.contains('connection')||sibling.classList.contains('muted'))){const next=sibling.nextElementSibling;sibling.remove();sibling=next;}const wires=wiresFor(n);heading.insertAdjacentHTML('afterend',wires.map(w=>{const outgoing=w.source.id===n.id,local=outgoing?w.connection.local:w.connection.remote,target=outgoing?w.target:w.source,remote=outgoing?w.connection.remote:w.connection.local;return `<div class="connection"><b>${esc(local)}</b><span>↔ ${esc(target.name)} / ${esc(remote)}</span><button data-wire-source="${esc(w.source.id)}" data-wire-index="${w.index}" aria-label="Remove connection">×</button></div>`;}).join('')||'<p class="muted" style="font-size:10px">No wires recorded yet.</p>');$$('[data-wire-source]').forEach(b=>b.onclick=()=>{node(b.dataset.wireSource).connections.splice(Number(b.dataset.wireIndex),1);changed('Removed pin connection');renderInspector();});};
const originalGraph=renderGraph;
renderGraph=function(){const wiring=view==='wiring';$('.canvas-caption').innerHTML=wiring?'PIN-TO-PIN WIRING <span>Select a board or pin to connect</span>':'PRODUCT ARCHITECTURE <span>Click a component to inspect</span>';$('.canvas-footer > span').textContent=wiring?'Colored lines = recorded electrical wires':'└─ Parent–child relationship';$('#canvas').classList.toggle('wiring-canvas',wiring);if(!wiring){originalGraph();return;}const list=project.nodes.filter(n=>categories[n.category][2]&&enabled.has(n.category)),positions=new Map();let y=25;for(let i=0;i<list.length;i+=2){const pair=list.slice(i,i+2);for(let j=0;j<pair.length;j++)positions.set(pair[j].id,{x:38+j*400,y,height:Math.max(132,92+pair[j].pins.length*25)});y+=Math.max(...pair.map(n=>positions.get(n.id).height))+65;}const width=720,height=Math.max(300,y);$('#graph').style.width=width+'px';$('#graph').style.height=height*zoom+'px';$('#nodes').style.transform=`scale(${zoom})`;$('#nodes').style.transformOrigin='0 0';const svg=$('#edges');svg.style.width=width+'px';svg.style.height=height+'px';svg.style.transform=`scale(${zoom})`;svg.style.transformOrigin='0 0';const colors=['#6189ab','#b99a58','#9f7cac','#6e9b7c','#bf827b'];svg.innerHTML=wireRecords().filter(w=>positions.has(w.source.id)&&positions.has(w.target?.id)).map((w,i)=>{const a=positions.get(w.source.id),b=positions.get(w.target.id),ai=w.source.pins.findIndex(p=>p.name===w.connection.local),bi=w.target.pins.findIndex(p=>p.name===w.connection.remote);const right=b.x>a.x||b.x===a.x,ax=a.x+(right?230:0),bx=b.x+(right?0:230),ay=a.y+85+ai*25,by=b.y+85+bi*25;const bend=right?65:-65;return `<path d="M ${ax} ${ay} C ${ax+bend} ${ay}, ${bx-bend} ${by}, ${bx} ${by}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="2.2"><title>${esc(w.source.name)} ${esc(w.connection.local)} ↔ ${esc(w.target.name)} ${esc(w.connection.remote)}</title></path>`;}).join('');$('#nodes').innerHTML=list.map(n=>{const p=positions.get(n.id);return `<article class="board-card ${selected===n.id?'selected':''}" style="left:${p.x}px;top:${p.y}px;width:230px;height:${p.height}px"><button class="board-heading" data-board="${esc(n.id)}"><span>▣</span><strong>${esc(n.name)}</strong><small>${esc(n.model||categories[n.category][0])}</small></button><div class="board-pins">${n.pins.map(pin=>`<button data-pin-board="${esc(n.id)}" data-pin-name="${esc(pin.name)}" title="Connect ${esc(pin.name)}"><i></i><span>${esc(pin.name)}</span><small>${esc(pin.type==='unspecified'?'':pin.type)}</small><i></i></button>`).join('')||'<button class="no-pins" data-board="'+esc(n.id)+'">＋ Select to add pins</button>'}</div><span class="board-hole"></span></article>`;}).join('')||'<p class="muted" style="padding:40px">No electronics in this view. Add a board or enable its category.</p>';$$('[data-board]').forEach(b=>b.onclick=()=>{selected=b.dataset.board;renderGraph();renderInspector();});$$('[data-pin-board]').forEach(b=>b.onclick=()=>{selected=b.dataset.pinBoard;renderGraph();renderInspector();openConnection(node(selected),b.dataset.pinName);});$('#zoomValue').textContent=Math.round(zoom*100)+'%';};
const originalSetView=setView;setView=function(v){const entering=view!==v;if(entering&&v==='wiring')zoom=Math.max(.25,Math.min(1,($('#canvas').clientWidth-12)/720));else if(entering&&view==='wiring')zoom=1;originalSetView(v);$('#wiringView').classList.toggle('selected',v==='wiring');$$('[data-filter]').forEach(c=>c.disabled=v!=='full'&&!categories[c.dataset.filter][2]);};$('#wiringView').onclick=()=>setView('wiring');
$('#componentForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return;const pins=pinList(f.pinNames);if(new Set(pins.map(p=>p.name.toLowerCase())).size!==pins.length||pins.some(p=>p.name.length>80)||pins.length>100){toast('Use up to 100 unique pin names, each up to 80 characters.');return;}const n={...f,name:f.name.trim(),id:uid(),parent:f.parent||null,quantity:Number(f.quantity),ready:false,voltage:'',interface:'',firmware:'',pins,connections:[],attachments:[]};delete n.pinNames;project.nodes.push(n);selected=n.id;enabled.add(n.category);setView('full');changed(`Added ${n.name}`);renderInspector();$('#componentDialog').close();toast('Component added. Select a pin to connect it to another component.');};
const originalBrief=brief;brief=function(){return originalBrief()+'\n\n## Defined pin inventories\n'+project.nodes.filter(n=>n.pins.length).map(n=>`### ${n.name} [${n.id}]\n`+n.pins.map(p=>`- ${p.name}: ${p.type||'unspecified'}${p.notes?' — '+p.notes:''}`).join('\n')).join('\n\n');};
function inferCategory(name){const s=name.toLowerCase();if(/\b(screw|nut|bolt|washer|standoff|fastener)s?\b/.test(s))return 'fastener';if(/\b(3d|printed|enclosure|bracket|shell|housing)\b/.test(s))return 'printed';if(/\b(servo|motor|actuator|stepper)\b/.test(s))return 'motor';if(/\b(sensor|bme\d+|dht\d+|mpu\d+|ttp\d+)\b/.test(s))return 'sensor';if(/\b(esp32\w*|esp8266|arduino|pico|teensy|devkit|stm32\w*|raspberry|board)\b/.test(s))return 'board';if(/\b(battery|supply|regulator|charger|power|buck)\b/.test(s))return 'power';return 'peripheral';}
const categoryAliases={'3d printed':'printed','3d printed part':'printed','3d printed parts':'printed','pcb':'board','controller':'board','electronics':'peripheral','electronic':'peripheral','screws':'fastener','motors':'motor','actuator':'motor','sensors':'sensor','mechanical part':'mechanical'};
function importPart(record,line){const name=String(record.name||'').trim();if(!name)throw Error(`Row ${line}: component name is empty.`);const raw=String(record.category||'').toLowerCase().trim();const category=raw?(categoryAliases[raw]||raw):inferCategory(name);if(!categories[category])throw Error(`Row ${line}: unknown category "${raw}". Use ${Object.keys(categories).join(', ')}.`);const quantity=Number(record.quantity||1);if(!Number.isInteger(quantity)||quantity<1||quantity>100000)throw Error(`Row ${line}: quantity must be a whole number from 1 to 100,000.`);return {id:String(record.id||uid()).trim(),parent:record.parent?.trim()||null,name,category,quantity,model:record.model||'',notes:record.notes||'',voltage:record.voltage||'',interface:record.interface||'',firmware:record.firmware||'',ready:['true','yes','1'].includes(String(record.ready||'').toLowerCase()),pins:pinList(record.pins),connections:[],attachments:[]};}
function resolveParents(nodes){const ids=new Map(nodes.map(n=>[n.id,n])),names=new Map();for(const n of nodes){const k=n.name.toLowerCase();if(!names.has(k))names.set(k,[]);names.get(k).push(n);}for(const n of nodes)if(n.parent&&!ids.has(n.parent)){const matches=names.get(n.parent.toLowerCase())||[];if(matches.length!==1)throw Error(`Parent "${n.parent}" for ${n.name} is ${matches.length?'ambiguous':'missing'}. Use a unique parent ID.`);n.parent=matches[0].id;}return nodes;}
function parseParts(text,format='text',name='Imported parts'){text=text.replace(/^\uFEFF/,'');let nodes=[];if(format==='csv'){const rows=csvRows(text),aliases={'component':'name','component name':'name','part':'name','part name':'name','description':'name','qty':'quantity','count':'quantity','type':'category','part number':'model','part_number':'model','parent id':'parent','parent_id':'parent','pin names':'pins'};const headers=(rows.shift()||[]).map(h=>{const k=h.trim().toLowerCase();return aliases[k]||k;});if(!headers.includes('name'))throw Error('CSV needs a name, part, component, or description column.');if(new Set(headers).size!==headers.length)throw Error('CSV has duplicate column names.');nodes=rows.map((row,i)=>importPart(Object.fromEntries(headers.map((h,j)=>[h,row[j]?.trim()||''])),i+2));}else{const stack=[];const lines=text.split(/\r?\n/);for(let i=0;i<lines.length;i++){const line=lines[i];if(!line.trim()||line.trim().startsWith('#'))continue;const spaces=line.match(/^\s*/)[0].replace(/\t/g,'  ').length;let content=line.trim().replace(/^[-*•]\s+/,'').replace(/^\d+\.\s+/,'');const fields=content.split('|').map(s=>s.trim());let record;if(fields.length>1){record={name:fields[0],quantity:fields[1]||1,category:fields[2]||'',parent:fields[3]||null,pins:fields[4]||''};}else{let quantity=1;let m=content.match(/^(\d+)\s*[x×]\s*(.+)$/i);if(m){quantity=m[1];content=m[2];}else {m=content.match(/^(.+?)\s+[x×]\s*(\d+)$/i);if(m){content=m[1];quantity=m[2];}}record={name:content,quantity};}const n=importPart(record,i+1);while(stack.length&&stack.at(-1).indent>=spaces)stack.pop();if(!n.parent&&stack.length)n.parent=stack.at(-1).id;nodes.push(n);stack.push({indent:spaces,id:n.id});}}if(!nodes.length)throw Error('No parts found. Enter one part per line or upload a parts CSV.');return validate({name,nodes:resolveParents(nodes)});}
function mergeParts(current,incoming){if(current.nodes.length+incoming.nodes.length>300)throw Error('The combined project exceeds the 300 component limit.');const ids=new Map(incoming.nodes.map(n=>[n.id,uid()]));const added=incoming.nodes.map(n=>({...structuredClone(n),id:ids.get(n.id),parent:n.parent?ids.get(n.parent):null,connections:n.connections.map(c=>({...c,target:ids.get(c.target)}))}));return validate({...current,nodes:[...structuredClone(current.nodes),...added]});}
function openImport(){const d=createModal(`<div class="dialog-heading"><div><div class="eyebrow">FROM PARTS LIST TO PRODUCT MAP</div><h2>Import parts</h2></div><button class="icon-button" data-dismiss>×</button></div><p class="muted">Upload CSV, TXT, or a Partmap JSON backup. Or paste a text list below. Review the generated map before importing.</p><label class="upload-list">Choose a parts list<input type="file" id="partsFile" accept=".csv,.txt,.text,.json"></label><details class="import-help"><summary>Supported list formats & examples</summary><p>CSV: name (or part/component/description), quantity (or qty), category, id, parent, model, notes, pins. Separate pins with semicolons. A parent can be a row ID or unique component name.</p><p>Text: one part per line. Use indentation for children; quantities like “4x M3 screws” or “M3 screws x4”. Structured lines: Name | quantity | category | parent | pin1;pin2.</p><a href="example-parts.csv" download>Example CSV</a> · <a href="example-parts.txt" download>Example text list</a></details><label>Paste a text parts list<textarea id="partsText" rows="7" placeholder="ESP32 DevKit\n  OLED display\n  Micro servo\nPrinted enclosure\n  4x M3 screws"></textarea></label><div class="form-row"><label>Project name<input id="importName" value="Imported parts"></label><label>Import into<select id="importMode"><option value="append">Add to current project</option><option value="replace">Replace current project</option><option value="wiring">Update wiring (no new components)</option></select></label></div><div id="partsError" role="alert"></div><div id="partsPreview"></div><p class="muted" id="importNote">Parts lists generate an assembly map. Categories are inferred when omitted; review them below. Electrical connections require explicit pin assignments.</p><div class="dialog-actions"><button class="button" id="previewParts">Preview map</button><button class="button primary" id="applyParts" disabled>Add parts & generate map</button></div>`);d.classList.add('wide-dialog');let pending=null,format='text',source='',revision=0;const text=d.querySelector('#partsText'),fileInput=d.querySelector('#partsFile'),preview=d.querySelector('#partsPreview'),error=d.querySelector('#partsError'),apply=d.querySelector('#applyParts'),mode=d.querySelector('#importMode');function invalidate(){pending=null;preview.innerHTML='';apply.disabled=true;error.textContent='';}function showPreview(){invalidate();try{const content=format==='json'?source:text.value;let raw=null;if(format==='json'){raw=JSON.parse(content);if(typeof wiringImportIsRelated==='function'&&Array.isArray(raw?.nodes)){mode.value=raw.wiringTask||wiringImportIsRelated(project,raw)?'wiring':'replace';mode.onchange();}}pending=format==='json'?validate(raw):parseParts(content,format,d.querySelector('#importName').value||'Imported parts');if(format==='json'&&!pending.baseline)pending.baseline=structuredClone(pending.nodes);if(format==='json'&&typeof checkWiringImport==='function'){checkWiringImport(project,pending,fileInput.files[0]?.name||'');mode.value=wiringImportIsRelated(project,pending)?'wiring':'replace';mode.onchange();}preview.innerHTML=`<strong>${pending.nodes.length} components · ${pending.nodes.filter(n=>n.parent).length} nested parts · ${pending.nodes.filter(n=>n.pins.length).length} with pins</strong><div class="import-table-wrap"><table><thead><tr><th>Component</th><th>Qty</th><th>Category</th><th>Parent</th></tr></thead><tbody>${pending.nodes.map(n=>`<tr><td>${esc(n.name)}</td><td>${n.quantity}</td><td>${esc(categories[n.category][0])}</td><td>${esc(pending.nodes.find(p=>p.id===n.parent)?.name||'Product root')}</td></tr>`).join('')}</tbody></table></div>`;apply.disabled=false;}catch(e){error.textContent=e.message;}}text.oninput=()=>{revision++;format='text';source='';fileInput.value='';invalidate();};d.querySelector('#importName').oninput=invalidate;fileInput.onchange=async()=>{const f=fileInput.files[0];if(!f)return;const request=++revision;invalidate();if(f.size>8*1024*1024){error.textContent='Use a file smaller than 8 MB.';return;}try{const content=await f.text();if(request!==revision)return;format=f.name.toLowerCase().endsWith('.csv')?'csv':f.name.toLowerCase().endsWith('.json')?'json':'text';source=content;text.value=format==='json'?'':content;d.querySelector('#importName').value=f.name.replace(/\.[^.]+$/,'');showPreview();}catch(e){error.textContent=e.message;}};mode.onchange=()=>{apply.textContent=mode.value==='wiring'?'Apply wiring update (no copies)':mode.value==='replace'?'Replace project & generate map':'Add parts & generate map';d.querySelector('#importNote').textContent=mode.value==='wiring'?'Updates existing components by stable ID. New boards, changed component counts, and rebuilt IDs are rejected. Your layout, checklist, and PCB are retained.':mode.value==='replace'?'This replaces your current map. Export a JSON backup first if you need to keep it.':'New parts are added to the current project. Categories inferred from names can be edited afterward. Pin connections require explicit assignments.';};d.querySelector('#previewParts').onclick=showPreview;apply.onclick=()=>{if(!pending)return;try{const count=pending.nodes.length;if(format==='json'&&typeof checkWiringImport==='function')checkWiringImport(project,pending,fileInput.files[0]?.name||'');if(mode.value==='wiring'){if(format!=='json')throw Error('Wiring updates require a full project JSON.');project=applyWiringUpdate(project,pending);selected=project.nodes.some(n=>n.id===selected)?selected:project.nodes[0]?.id;}else if(mode.value==='append'){if(format==='json'&&typeof guardJsonAppend==='function')guardJsonAppend(project,pending);project=mergeParts(project,pending);selected=project.nodes.at(-count)?.id;}else{project=validate(pending);project.baseline=project.baseline||structuredClone(project.nodes);selected=project.nodes[0]?.id;}enabled=new Set(Object.keys(categories));$$('[data-filter]').forEach(c=>c.checked=true);setView('full');changed(mode.value==='wiring'?`Applied wiring update to ${count} existing components; inventory unchanged`:`Imported ${count} components from a parts list`);renderInspector();d.close();toast(mode.value==='wiring'?`Updated wiring on ${count} existing components. No copies created.`:`Generated map from ${count} imported components`);}catch(e){error.textContent=e.message;}};d.showModal();}
$('#importBtn').onclick=openImport;$('#importBtn').title='Generate a map from CSV or text, or restore a JSON backup';
const originalSuggestions=suggestions;suggestions=function(){return originalSuggestions().filter(s=>!project.nodes.some(n=>wiresFor(n).length&&s===`${n.name}: document power, ground, and signal connections.`));};
render();
